3:  * cruise boost: is the boost demand HELD (Shift in the space scheme) and
4:  * is it ALLOWED at the predicted position (shared `cruiseAllowedAt`)?
5:  *
6:  * Written by the ship prediction loop (render rate) from the CURRENT input
7:  * + predicted position; the HUD tag (CRUISE / CRUISE BLOCKED) subscribes.
8:  * Emit-on-change: a key frame only re-notifies on held/allowed changes, so
9:  * the 60 fps loop costs the HUD nothing while the values stay stable.
10:  */
11: 
12: /** The HUD-visible cruise state. */
13: export interface CruiseState {
14:   /** Boost demand held (Shift pressed in the space scheme). */
15:   held: boolean;
16:   /** `cruiseAllowedAt(predicted pos)` — cruise can engage here. */
17:   allowed: boolean;
18: }
19: 
20: const INITIAL: CruiseState = { held: false, allowed: true };
21: let state: CruiseState = INITIAL;
22: const listeners = new Set<(s: CruiseState) => void>();
23: 
24: /** Publish the cruise state (emit-on-change). */
25: export function setCruiseState(next: CruiseState): void {
26:   if (next.held === state.held && next.allowed === state.allowed) return;
27:   state = next;
28:   for (const l of listeners) l(next);
29: }
30: 
31: /** The current cruise state. */
32: export function cruiseState(): CruiseState {
33:   return state;
34: }
35: 
36: /** Subscribe; the listener fires immediately with the current state. */
37: export function cruiseStateSubscribe(listener: (s: CruiseState) => void): () => void {
38:   listeners.add(listener);
39:   listener(state);
40:   return () => listeners.delete(listener);
41: }
42: 
43: /** Test seam. */
44: export function __resetCruiseState(): void {
45:   state = INITIAL;
46:   listeners.clear();
47: }

